/**
 * The stem lexicon of the Korean adapter: a HEADWORD STEM → the dictionary entries filed under it. Not a form index: Korean builds its
 * written forms by chaining particles and endings on a stem, so the forms of one word are not a finite list (docs/korean/PLAN.md). The
 * analyser (korean/analyze.ts) finds the stems an 어절 may begin with, looks them up here, and matches the rest by rule.
 *
 * Lexicons, both GENERATED by scripts/ko-build-lexicon.mts from the Wiktionary extract of kaikki.org (CC BY-SA 4.0):
 *   ko-core             the closed-class words and the commonest headwords, compiled into the analyser (korean/generated/core.ts), so
 *                       that a host with no assets still reads ordinary prose.
 *   kaikki-ko-lexicon   every headword of the extract, SHARDED (public/lexicon/ko/standard/), loaded on demand by the shared loader
 *                       (korean/shards.ts) and installed beside the core.
 *
 * Stem key: a predicate (tag VV, VA, VX, VCP, VCN) is filed under its headword WITHOUT the final 다 (먹다 → 먹, 예쁘다 → 예쁘, 이다 → 이);
 * anything else under its headword as written, through `koKey`. A row never invents anything: the headword, its class, its conjugation
 * class, its gloss and its Hanja are the source's.
 */

/** Conjugation class of a predicate, read off the source's own conjugation table (never guessed from the stem's shape). 'R' = regular, and the table shows it. */
export type KoIrregular = 'R' | 'D' | 'B' | 'S' | 'H' | 'Reu' | 'Reo' | 'U' | 'Ha';

/** Sejong-style class of a headword. */
export type KoTag = 'NNG' | 'NNP' | 'NNB' | 'NP' | 'NR' | 'VV' | 'VA' | 'VX' | 'VCP' | 'VCN' | 'MM' | 'MAG' | 'MAJ' | 'IC' | 'XPN' | 'XSN' | 'XSV' | 'XSA';

export const KO_PREDICATE_TAGS: ReadonlySet<string> = new Set(['VV', 'VA', 'VX', 'VCP', 'VCN']);

export interface KoLexEntry {
  /** Headword as the dictionary writes it: 먹다, 학생. */
  lemma: string;
  /**
   * The SOURCE's own homonym number (the entry's etymology number on its page), set only when the headword has two or more entries of
   * this class. Never a position in a file: the core and every shard read the same field, so the same word has the same number everywhere.
   */
  hom?: number;
  tag: KoTag;
  /** A derived passive or causative verb, as the source relates it (보이다 from 보다): its voice and its base verb's headword. */
  voice?: 'Pass' | 'Caus';
  base?: string;
  /** Conjugation class of a predicate. Absent: the source gives no conjugation table for it (the analyser then tries what the stem's shape allows and says so). */
  irr?: KoIrregular;
  /** First gloss of the first sense, at most 80 characters. */
  gloss?: string;
  /** Hanja of a Sino-Korean word, when the source states it. */
  hanja?: string;
  /** The source's own pronunciation respelling in Hangul, when it gives one (먹따). */
  pron?: string;
  /** Occurrences in the priors corpus (KO_SOURCE_IDS.priors); absent or 0 when unseen. */
  n?: number;
}

export interface KoLexicon {
  schema: 1;
  id: 'ko-core' | 'kaikki-ko-lexicon' | string;
  /** A SHARD of a larger lexicon: the prefix of the letters its keys share (hangul.ts `koShardLetters`). */
  shard?: string;
  source: { label: string; licence: string; url: string; retrieved?: string; sha256?: string; note?: string };
  built: string;
  /** stem key → entries, the commonest first. */
  entries: Record<string, KoLexEntry[]>;
  stats?: Record<string, number>;
}

export interface KoLexHit { lexicon: KoLexicon; key: string; entry: KoLexEntry }

const installed: KoLexicon[] = [];
const idOf = (x: { id: string; shard?: string }): string => `${x.id}\u0000${x.shard ?? ''}`;

/** Installs (or replaces) a lexicon or a shard of one. Later lookups see it at once. */
export function installKoreanLexicon(lexicon: KoLexicon): void {
  const at = installed.findIndex((x) => idOf(x) === idOf(lexicon));
  if (at >= 0) installed[at] = lexicon; else installed.push(lexicon);
}

/** Removes a lexicon (every shard of it when `shard` is undefined and it has shards). */
export function uninstallKoreanLexicon(id: string, shard?: string): void {
  for (let i = installed.length - 1; i >= 0; i--) if (installed[i].id === id && (shard === undefined || installed[i].shard === shard)) installed.splice(i, 1);
}

/** The ids of what is installed (a shard as `id#shard`), for diagnostics and tests. */
export const installedKoreanLexicons = (): string[] => installed.map((x) => (x.shard !== undefined ? `${x.id}#${x.shard}` : x.id));

/**
 * The entries filed under a stem key, over every installed lexicon. The same headword, class and homonym number from two lexicons (the
 * core and a shard hold the commonest words twice) is returned once, from the lexicon installed LAST (the fuller record).
 */
export function lookupKoreanStem(stemKey: string): KoLexHit[] {
  const seen = new Map<string, KoLexHit>();
  for (const lexicon of installed) {
    const rows = lexicon.entries[stemKey];
    if (!rows) continue;
    for (const entry of rows) seen.set(`${entry.lemma}\u0000${entry.tag}\u0000${entry.hom ?? 0}`, { lexicon, key: stemKey, entry });
  }
  return [...seen.values()].sort((a, b) => (b.entry.n ?? 0) - (a.entry.n ?? 0) || (a.entry.hom ?? 0) - (b.entry.hom ?? 0) || (a.entry.tag < b.entry.tag ? -1 : a.entry.tag > b.entry.tag ? 1 : 0));
}

/** True when any installed lexicon files something under the key. */
export const hasKoreanStem = (stemKey: string): boolean => installed.some((x) => x.entries[stemKey] !== undefined);

/**
 * The letters a lexicon key is sharded by (the shared loader's `letters`; the build uses the same function, so a key is always looked
 * for where it was filed). A key beginning with a Hangul syllable: that syllable's jamo, lead then vowel then final (hangul.ts
 * `koShardLetters`). A key beginning with a Hanja (an entry is ALSO filed under its Hanja spelling, so 學校에서 on a page reaches 학교):
 * 'H' and the first character's code point in hex without its last two digits (學 U+5B78 → 'H5b'), so the Hanja keys spread over
 * some 80 shards instead of one. Anything else: '' (the loader's '_' shard).
 */
export function koLexiconShardLetters(key: string): string {
  const cp = key.codePointAt(0);
  if (cp === undefined) return '';
  if (cp >= 0xac00 && cp <= 0xd7a3) {
    const i = cp - 0xac00;
    const lead = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'[Math.floor(i / 588)];
    const vowel = 'ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ'[Math.floor((i % 588) / 28)];
    const final = ['', 'ㄱ', 'ㄲ', 'ㄳ', 'ㄴ', 'ㄵ', 'ㄶ', 'ㄷ', 'ㄹ', 'ㄺ', 'ㄻ', 'ㄼ', 'ㄽ', 'ㄾ', 'ㄿ', 'ㅀ', 'ㅁ', 'ㅂ', 'ㅄ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'][i % 28];
    return lead + vowel + final;
  }
  const hanja = (cp >= 0x4e00 && cp <= 0x9fff) || (cp >= 0x3400 && cp <= 0x4dbf) || (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0x20000 && cp <= 0x2ffff);
  return hanja ? `H${(cp >> 8).toString(16)}` : '';
}

const SUPERSCRIPT = ['⁰', '¹', '²', '³', '⁴', '⁵', '⁶', '⁷', '⁸', '⁹'];
const SUPERSCRIPT_RUN = /[⁰¹²³⁴-⁹]+$/u;

/**
 * The lemma string of a homonym: the headword with the dictionary's number as superscript digits, the way dictionaries print it
 * (눈¹ eye, 눈² snow). It is the identity of the learner's item (`lemma:ko:눈²:NOUN`). `n` undefined or below 1: the bare headword.
 */
export function koHomonymLemma(lemma: string, n: number | undefined): string {
  if (!n || n < 1 || !Number.isInteger(n)) return lemma;
  return lemma + String(n).split('').map((d) => SUPERSCRIPT[Number(d)]).join('');
}

/** The headword as written, without a homonym number: what is spoken, searched and looked up as a spelling. */
export const koBareLemma = (lemma: string): string => lemma.replace(SUPERSCRIPT_RUN, '');

/** The homonym number a lemma string carries, or undefined. */
export function koHomonymNumber(lemma: string): number | undefined {
  const m = SUPERSCRIPT_RUN.exec(lemma);
  if (!m) return undefined;
  return Number([...m[0]].map((c) => SUPERSCRIPT.indexOf(c)).join(''));
}

/** The lemma string of a lexicon entry: numbered when the entry has a homonym number. */
export const koEntryLemma = (entry: Pick<KoLexEntry, 'lemma' | 'hom'>): string => koHomonymLemma(entry.lemma, entry.hom);

/** The stem key of a headword of a given class: a predicate loses its final 다. */
export function koStemKey(lemma: string, tag: string): string {
  return KO_PREDICATE_TAGS.has(tag) && lemma.length > 1 && lemma.endsWith('다') ? lemma.slice(0, -1) : lemma;
}
